var SEASON_TEMP_CURVE = [0.0, 0.04, 0.22, 0.5, 0.76, 0.92, 1.0, 0.94, 0.72, 0.45, 0.18, 0.05];
var WIND_DIRS_8 = ["\u0421", "\u0421\u0412", "\u0412", "\u042E\u0412", "\u042E", "\u042E\u0417", "\u0417", "\u0421\u0417"];
function clampNum(v: number, min: number, max: number) {
  return Math.max(min, Math.min(max, v));
}
function round1(v: number) {
  return Math.round(v * 10) / 10;
}
function buildMonthlyClimate(opts: {
  city: string;
  region?: string;
  lat?: number;
  lon?: number;
  elevationM?: number;
  tSummerDay: number;
  tSummerNight?: number;
  tWinterDay: number;
  tWinterNight?: number;
  rainProb?: number;
  avgWind?: number;
  windDirWinter?: string;
  windDirSummer?: string;
}) {
  const tSummerDay = opts.tSummerDay;
  const tSummerNight = opts.tSummerNight ?? Math.round((tSummerDay - 9.5) * 10) / 10;
  const tWinterDay = opts.tWinterDay;
  const tWinterNight = opts.tWinterNight ?? Math.round((tWinterDay - 5.2) * 10) / 10;
  const baseRain = clampNum(opts.rainProb ?? 0.25, 0.1, 0.6);
  const baseWind = opts.avgWind ?? 3.3;
  const months = SEASON_TEMP_CURVE.map((w) => {
    const tDay = round1(tWinterDay + (tSummerDay - tWinterDay) * w);
    const tNight = round1(tWinterNight + (tSummerNight - tWinterNight) * w);
    const tMax = Math.round(tDay + 9);
    const tMin = Math.round(tNight - 13);
    const snowProb = tDay <= -2 ? 0.95 : tDay <= 2 ? 0.7 : tDay <= 7 ? 0.25 : tDay <= 12 ? 0.05 : 0;
    const precipProb = Math.round(clampNum(baseRain * (1.15 - 0.3 * w) + 0.28, 0.22, 0.78) * 100) / 100;
    const avgWind = round1(baseWind * (1.16 - 0.24 * w));
    const humidity = Math.round(clampNum(86 - 17 * w, 52, 90));
    const windDir = w < 0.45 ? (opts.windDirWinter || "\u042E\u0417") : (opts.windDirSummer || "\u0417");
    return { tDay, tNight, tMax, tMin, precipProb, snowProb, avgWind, humidity, windDir };
  });
  return {
    city: opts.city,
    region: opts.region || "\u0420\u043E\u0441\u0441\u0438\u044F",
    lat: opts.lat ?? 55.75,
    lon: opts.lon ?? 37.62,
    elevationM: opts.elevationM ?? 120,
    months
  };
}
