  db2.foreignScoutDecisions.unshift(entry);
  if (db2.foreignScoutDecisions.length > 80) db2.foreignScoutDecisions.length = 80;

  if (!Array.isArray(db2.clubNotifications)) db2.clubNotifications = [];
