        if (aiRes.wage && typeof aiRes.wage === "string") wage = aiRes.wage.slice(0, 40);
        if (aiRes.triggerReason && typeof aiRes.triggerReason === "string") triggerReason = aiRes.triggerReason.slice(0, 180);
