    const baseOvr = Number(pObj.ovr || pObj.rating || 70);
    const age = Number(pObj.age || 25);
    const isBenchSpot = !didPlay || (!r?.started && Number(r?.min || 0) <= 25) || st.isBenchTarget;

    // 1. Проверка на отзыв существующего висящего предложения (только если играл и провалился или просрочено)
