  if (!p) throw new Error("Игрок не найден в базе");
  if (!seller) throw new Error("Клуб-продавец не найден");
  if (p.teamId !== seller.id) {
    throw new Error(`Игрок ${p.name} уже не числится в составе «${seller.name}»`);
  }

