  const sotH = Math.max(targetH, targetH + Math.floor(lightRand() * 4) + (possH >= 50 ? 2 : 1));
  const sotA = Math.max(targetA, targetA + Math.floor(lightRand() * 4) + (possH < 50 ? 2 : 1));
  const shH = Math.max(sotH + 2, sotH + 3 + Math.floor(lightRand() * 7));
  const shA = Math.max(sotA + 2, sotA + 3 + Math.floor(lightRand() * 7));
