  const xgA = +clamp(targetA * 0.48 + (sotA - targetA) * 0.14 + (shA - sotA) * 0.04 + 0.12, Math.max(0.15, targetA * 0.35), 4.8).toFixed(2);

  const diffGoals = targetH - targetA;
  let scenarioHint = "упорная ничья";
  if (targetH === 0 && targetA === 0) scenarioHint = "плотная тактическая борьба и безголевая ничья 0:0";
  else if (diffGoals === 0) scenarioHint = targetH >= 2 ? "результативная открытая ничья" : "ничья в равной борьбе";
  else if (diffGoals >= 3) scenarioHint = "крупная победа хозяев";
  else if (diffGoals === 2) scenarioHint = "уверенная победа хозяев";
  else if (diffGoals === 1) scenarioHint = "напряжённая победа хозяев с минимальным перевесом";
  else if (diffGoals <= -3) scenarioHint = "крупная выездная победа гостей";
  else if (diffGoals === -2) scenarioHint = "уверенная выездная победа гостей";
  else scenarioHint = "трудовая победа гостей с разницей в один мяч";

