  const score = e.score ? `${e.score[0]}:${e.score[1]}` : `${f.hg ?? 0}:${f.ag ?? 0}`;
  const pre = typeof e.min === "number" && e.min < 0;
  const minute = pre ? "\u0434\u043E \u043C\u0430\u0442\u0447\u0430" : e.min !== void 0 && e.min !== null ? `${e.min}'` : "";
