    if (awards.bestPlayer) {
      const bp = awards.bestPlayer;
      lines.push(`⭐ <b>Лучший игрок тура:</b> ${esc(bp.name)} (${esc(bp.pos)}, «${esc(bp.team)}») — оценка <b>${bp.rating}</b>${bp.stat ? ` · ${esc(bp.stat)}` : ""}`);
    }
    if (awards.coachOfRound) {
      const co = awards.coachOfRound;
      lines.push(`👔 <b>Тренер тура:</b> ${esc(co.coach?.name || "Тренер")} («${esc(co.teamName)}»)${co.reason ? ` — ${esc(co.reason)}` : ""}`);
    }
    if (awards.starters?.length) {
      lines.push("");
      lines.push(`📋 <b>Сборная тура (${esc(awards.formation || "4-3-3")}):</b>`);
      for (const pl of awards.starters) {
        lines.push(`• <b>${esc(pl.pos)}</b> ${esc(pl.name)} («${esc(pl.team)}») — <b>${pl.rating}</b>${pl.stat ? ` (${esc(pl.stat)})` : ""}`);
      }
    }
    if (db.settings.siteUrl) {
      lines.push("");
      lines.push(`🌐 Все награды: ${esc(db.settings.siteUrl)}/#/awards`);
    }
