// Роут для прямого управления дисциплиной игрока:
app.post("/api/admin/player/discipline", admin, (req, res) => {
  const b = req.body;
  const p = b.id && player(b.id);
  if (!p) return fail(res, "Игрок не найден");

  const reqBanComp = b.banComp !== undefined ? String(b.banComp || "").trim() : undefined;
  const banCompNorm = normDiscComp(reqBanComp);
  if (b.clearBan) {
    if (b.clearAllBans || !reqBanComp || reqBanComp === "all") {
      p.banLeft = 0;
      p.banByComp = {};
      p.banUntil = null;
      p.banLabel = "";
      p.banReason = "";
    } else if (banCompNorm) {
      if (p.banByComp && typeof p.banByComp === "object") delete p.banByComp[banCompNorm];
      if (!Object.keys(p.banByComp || {}).length && !p.banLeft && b.banUntil === null) {
        p.banUntil = null;
        p.banLabel = "";
        p.banReason = "";
      }
    }
  } else {
    if (banCompNorm) {
      if (b.banLeft !== undefined) {
        const left = Math.max(0, parseInt(b.banLeft, 10) || 0);
        p.banByComp = cleanBanByComp(p.banByComp);
        if (left > 0) {
          p.banByComp[banCompNorm] = {
            left,
            reason: b.banReason !== undefined ? String(b.banReason || "").trim() : (p.banByComp[banCompNorm]?.reason || ""),
            label: b.banLabel !== undefined && String(b.banLabel || "").trim()
              ? String(b.banLabel || "").trim()
              : `${left} ${ruPlural(left, "\u043C\u0430\u0442\u0447", "\u043C\u0430\u0442\u0447\u0430", "\u043C\u0430\u0442\u0447\u0435\u0439")}`
          };
        } else {
          delete p.banByComp[banCompNorm];
        }
      }
      if (b.banUntil !== undefined) p.banUntil = b.banUntil ? String(b.banUntil).trim() : null;
      if (b.banUntil) {
        if (b.banLabel !== undefined) p.banLabel = String(b.banLabel || "").trim();
        if (b.banReason !== undefined) p.banReason = String(b.banReason || "").trim();
      }
    } else {
      if (b.banLeft !== undefined) p.banLeft = Math.max(0, parseInt(b.banLeft, 10) || 0);
      if (b.banUntil !== undefined) p.banUntil = b.banUntil ? String(b.banUntil).trim() : null;
      if (b.banLabel !== undefined) p.banLabel = String(b.banLabel || "").trim();
      if (b.banReason !== undefined) p.banReason = String(b.banReason || "").trim();
    }
  }

  if (b.clearInjury || b.injuryActive === false) {
    p.out = null;
  } else if ("out" in b) {
    if (!b.out) {
      p.out = null;
    } else if (typeof b.out === "object" && b.out.until) {
      const dCount = b.out.days ? Math.max(1, Math.round(+b.out.days)) : 1;
      p.out = {
        until: String(b.out.until).trim(),
        days: dCount,
        label: b.out.label ? String(b.out.label).trim() : daysLabel(dCount),
        reason: b.out.reason ? String(b.out.reason).trim() : (b.out.label ? String(b.out.label).trim() : "Травма")
      };
    }
  }

  p.updatedAt = new Date().toISOString();
  pruneUnavailableFromSavedLineups();
  save();
  res.json({ ok: 1, player: pubPlayer(p) });
});

