function buildAdminAiStatusPayload() {
  syncSecretsFromDisk();
  const now = Date.now();
  const keysMeta = getGeminiKeysWithMeta();
  const activeModel = getGeminiModel();
  const proxyUrl = workerBase();

  let readyKeys = 0;
  let coolingKeys = 0;
  let invalidKeys = 0;
  let totalRpdToday = 0;
  let totalTokensToday = 0;
  let totalOkToday = 0;
  let totalErrorsToday = 0;
  let totalRateLimitsToday = 0;
  let totalLatencySum = 0;
  let totalLatencyCount = 0;

  const keysOut = keysMeta.map((km, idx) => {
    const st = ensureKeyStat(km.key);
    const kc = getCooldownEntry(km.key, activeModel, now);
    const kcUntil = getCooldownUntil(kc);
    const keyBlocked = !!kc && kcUntil > now;

    let status = "ready";
    let cooldownRemainingSec = 0;
    if (keyBlocked) {
      cooldownRemainingSec = Math.ceil((kcUntil - now) / 1000);
      if (kc?.authInvalid) {
        status = "auth_error";
        invalidKeys++;
      } else {
        status = kc?.daily ? "daily_limit" : "cooling";
        coolingKeys++;
      }
    } else {
      readyKeys++;
    }

    totalRpdToday += st.todayRequests;
    totalTokensToday += st.todayTotalTokens;
    totalOkToday += st.todayOk;
    totalErrorsToday += st.todayErrors;
    totalRateLimitsToday += st.todayRateLimits;
    totalLatencySum += st.totalLatencyMs;
    totalLatencyCount += st.latencySamples;

    return {
      index: idx + 1,
      keyId: km.keyId,
      tail: km.tail,
      source: km.source,
      status,
      cooldownRemainingSec,
      rpdToday: st.todayRequests,
      okToday: st.todayOk,
      errorsToday: st.todayErrors,
      rateLimitsToday: st.todayRateLimits,
      promptTokensToday: st.todayPromptTokens,
      outputTokensToday: st.todayOutputTokens,
      thoughtTokensToday: st.todayThoughtTokens,
      tokensToday: st.todayTotalTokens,
      avgMs: st.latencySamples ? Math.round(st.totalLatencyMs / st.latencySamples) : 0,
      lastUsedAt: st.lastUsedAt,
      lastOkAt: st.lastOkAt,
      lastErrorAt: st.lastErrorAt,
      lastError: st.lastErrorMsg,
      lastErrorStatus: st.lastErrorStatus
    };
  });

  return {
    ok: 1,
    today: aiTodayStr(),
    models: {
      primary: activeModel,
      effective: getEffectiveGeminiModel(now),
      presets: GEMINI_PRESET_MODELS,
      mistral: HARDCODED.mistralKeys.length || process.env.MISTRAL_API_KEY ? getEffectiveMistralModel(now) : "",
      mistralPrimary: HARDCODED.mistralModel,
      mistralFallback: HARDCODED.mistralFallbackModel,
      mistralUsingFallback: isMistralUsingFallback(now),
      openrouter: HARDCODED.openrouterKeys.length || process.env.OPENROUTER_API_KEY ? HARDCODED.openrouterModel : ""
    },
    database: {
      active: pgActive,
      configured: !!HARDCODED.databaseUrl,
      maskedUrl: maskDatabaseUrl(HARDCODED.databaseUrl),
      error: pgLastError
    },
    proxy: {
      active: !!proxyUrl,
      workerUrl: proxyUrl,
      hasWorkerSecret: !!HARDCODED.workerSecret
    },
    appConfig: {
      maxAiCalls: Number(db.settings.maxAiCalls || 10),
      aiParallel: Number(db.settings.aiParallel || 2),
      aiLeadSec: Number(db.settings.aiLeadSec ?? 90),
      chunks: Number(db.settings.chunks || 2),
      grounding: !!db.settings.grounding,
      auto: !!db.settings.auto,
      interviewLimit: 3
    },
    summary: {
      totalKeys: keysOut.length,
      readyKeys,
      coolingKeys,
      invalidKeys,
      rpdToday: totalRpdToday,
      tokensToday: totalTokensToday,
      okToday: totalOkToday,
      errorsToday: totalErrorsToday,
      rateLimitsToday: totalRateLimitsToday,
      avgMs: totalLatencyCount ? Math.round(totalLatencySum / totalLatencyCount) : 0,
      successRate: totalRpdToday ? Math.round((totalOkToday / totalRpdToday) * 100) : 100
    },
    keys: keysOut,
    recentLog: (db.llmlog || []).slice(-30).reverse()
  };
}
